void
wglSystemFontOutlines(unsigned c, float extrude)
{
    if (c < sizeof font / sizeof font[0] ) {
        const CallList *callList = &font[c];

        for (size_t i = 0; i < callList->length; ++i) {
            const Call *call = &callList->calls[i];
            const float *args = call->args;

            switch (call->function) {
            case F_BEGIN:
                glBegin(args[0]);
                break;
            case F_FRONTFACE:
                glFrontFace(args[0]);
                break;
            case F_VERTEX3F:
                glVertex3f(args[0], args[1], args[2] * extrude);
                break;
            case F_NORMAL3F:
                glNormal3f(args[0], args[1], args[2]);
                break;
            case F_END:
                glEnd();
                break;
            case F_TRANSLATEF:
                glTranslatef(args[0], args[1], args[2]);
                break;
            }
        }

    }
}
